// === Tab: mySketch.js ===
let url = 'https://coolors.co/ffffff-efeeec-c3ae85-9a7539-8e6a34-694c16-221105-c55827-fef9b5';
let palette = url.split('/')[3].split('-').map(c => '#' + c);
let vmin, vmax;
let gl, glsl;
let tex, texSize;
let img;

function preload() {
  glsl = loadShader('https://openprocessing.org/sketch/1534234/files/shader.vert', 'shader.frag');
  img = loadImage('https://openprocessing.org/sketch/1534234/files/paper_1024.jpg');
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  // createCanvas(800, 800, WEBGL);
  noStroke();
  gl = drawingContext;
  vmin = max(width, height);
  vmax = max(width, height);
  texSize = 512;
  tex = createGraphics(texSize, texSize);
  let lg = tex.drawingContext.createLinearGradient(0, 0, texSize, 0);
  for (let i = 0; i < palette.length; i++) {
    let pct = i / (palette.length - 1);
    lg.addColorStop(pct, palette[i]);
  }
  tex.drawingContext.fillStyle = lg;
  tex.rect(0, 0, texSize, texSize);
}

function draw() {
  let sec = millis() / 1000;
  background(0);

  shader(glsl);
  glsl.setUniform('uTime', sec);
  glsl.setUniform('uTex', tex);
  glsl.setUniform('uImg', img);
  // texture(tex);
  plane(vmax);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed() {
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}


